functionProofs.body:
BEGIN
 IF NEW."subjectKind" = 'public_cash' OR NEW."impactKind" = 'public_cash_funds_decrease' THEN
   IF NOT coalesce(NEW."subjectRole" = 'actual_payer' AND NEW."subjectKind" = 'public_cash'
       AND NEW."sourceType" = 'payment_execution'
       AND public."jg_registered_payment_impact_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."subjectKind",NEW."subjectId",NEW."impactKind",NEW."sourceImpactKey",NEW."direction",NEW."idempotencyKey"),FALSE) THEN
     RAISE EXCEPTION 'public cash impact must be the exact canonical registered source posting';
   END IF;
 END IF;
 RETURN NEW;
END

BEGIN
 IF NEW."sourceType" = 'payment_execution' AND EXISTS (
   SELECT 1 FROM public."RegisteredPaymentFunding" funding WHERE funding."executionId" = NEW."sourceBusinessId"
 ) THEN
   -- Permanent graph proof only: never re-run current actor/round/history/date
   -- or the initial account CAS when a later projection is appended.
   PERFORM public."jg_assert_registered_payment_intercompany_complete"(NEW."sourceBusinessId");
 END IF;
 RETURN NULL;
END

BEGIN
 RETURN QUERY SELECT p."id",p."operatingLedgerEffectiveDate" FROM public."Project" p WHERE p."id"=project_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'registered payment requires an existing project scope'; END IF;
END

DECLARE covered_id TEXT;
BEGIN
 IF pg_catalog.cardinality(NEW."coveredExecutionIds") <> (SELECT pg_catalog.count(DISTINCT id) FROM pg_catalog.unnest(NEW."coveredExecutionIds") id) THEN
   RAISE EXCEPTION 'covered payment identities must be unique';
 END IF;
 FOREACH covered_id IN ARRAY NEW."coveredExecutionIds" LOOP
   IF NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentFunding" f WHERE f."executionId" = covered_id AND f."accountId" = NEW."accountId") THEN
     RAISE EXCEPTION 'covered payment must be an existing fact of the same account';
   END IF;
 END LOOP;
 RETURN NEW;
END

DECLARE eid TEXT; f public."RegisteredPaymentFunding"; e public."PaymentExecution";
 a public."RegisteredFundAccount"; r public."FundAccountBalanceRegistration"; total NUMERIC; line_count BIGINT;
BEGIN
 eid := NEW."executionId";
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = eid;
 SELECT * INTO STRICT e FROM public."PaymentExecution" WHERE "id" = eid;
 SELECT * INTO STRICT a FROM public."RegisteredFundAccount" WHERE "id" = f."accountId";
 SELECT * INTO STRICT r FROM public."FundAccountBalanceRegistration" WHERE "id" = f."balanceRegistrationId" AND "accountId" = a."id";
 IF e."amountCents" <= 0 OR r."status" <> 'confirmed' OR
    NOT COALESCE(((a."kind" = 'company' AND f."actualPayerKind" = 'participating_company' AND f."actualPayerId" = a."companyEntityId" AND f."actualPayerSnapshot"->>'companyEntityId' = a."companyEntityId") OR
         (a."kind" = 'public_cash' AND a."companyEntityId" IS NULL AND f."actualPayerKind" = 'public_cash' AND f."actualPayerId" = 'public_cash' AND f."actualPayerSnapshot"->>'scopeKey' = 'public_cash')),FALSE) THEN
   RAISE EXCEPTION 'registered payment requires the frozen canonical account identity';
 END IF;
 SELECT coalesce(pg_catalog.sum(p."amountCents"),0),pg_catalog.count(*) INTO total,line_count FROM public."RegisteredFundPaymentAllocation" p WHERE p."executionId" = eid;
 IF (f."openingTreatment" = 'included' AND line_count <> 0) OR
    (f."openingTreatment" = 'not_included' AND (line_count = 0 OR total <> e."amountCents")) THEN
   RAISE EXCEPTION 'registered payment allocations do not conserve the canonical payment';
 END IF;
 IF EXISTS (SELECT 1 FROM public."RegisteredFundPaymentAllocation" p JOIN public."FundAccountSourceBatch" s ON s."id" = p."sourceBatchId" WHERE p."executionId" = eid AND (p."accountId" <> a."id" OR s."registrationId" <> r."id")) THEN
   RAISE EXCEPTION 'registered payment source belongs to a different frozen reconciliation';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentEvent" event WHERE event."executionId" = eid AND event."eventType" = 'payment_execution.registered' AND event."payload"->>'executionId' = eid AND event."payload"->>'accountId' = a."id" AND event."payload"->>'balanceRegistrationId' = r."id") THEN
   RAISE EXCEPTION 'registered payment requires its same-transaction durable event';
 END IF;
 IF (SELECT pg_catalog.count(*) FROM public."AuditLog" audit WHERE audit."action" = 'payment.execution.record'
       AND audit."businessType" = 'payment_request' AND audit."businessId" = e."paymentRequestId" AND audit."actorUserId" = e."executedByUserId"
       AND audit."metadata"->>'executionId' = e."id" AND audit."metadata"->>'idempotencyKey' = e."idempotencyKey"
       AND pg_catalog.jsonb_typeof(audit."metadata"->'amountCents') = 'string' AND audit."metadata"->>'amountCents' = e."amountCents"::TEXT
       AND audit."metadata"->'voucherFileId' = 'null'::JSONB AND audit."metadata"->'voucherPending' = 'true'::JSONB
       AND audit."metadata"->'actualPayer'->>'kind' = f."actualPayerKind" AND audit."metadata"->'actualPayer'->>'id' = f."actualPayerId"
       AND audit."metadata"->'actualPayer'->'snapshot' = f."actualPayerSnapshot"
       AND audit."metadata"->'payer'->>'paymentSubjectType' = 'our_company'
       AND audit."metadata"->'payer'->>'companyEntityIdSnapshot' = e."companyEntityIdSnapshot"
       AND audit."metadata"->'payer'->>'companyEntityNameSnapshot' = e."companyEntityNameSnapshot"
       AND audit."metadata"->'payer'->>'companyEntityCreditCodeSnapshot' = e."companyEntityCreditCodeSnapshot"
       AND audit."metadata"->>'paidAt' = pg_catalog.to_char(e."paidAt",'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       AND audit."metadata"->'funding'->>'kind' = 'registered_fund_account'
       AND audit."metadata"->'funding'->>'openingTreatment' = f."openingTreatment"
       AND audit."metadata"->'funding'->>'accountId' = a."id" AND audit."metadata"->'funding'->>'balanceRegistrationId' = r."id"
       AND audit."metadata"->>'fromStatus' = (SELECT event."payload"->'writeAuthority'->>'requestStatusBeforeExecution' FROM public."RegisteredPaymentEvent" event WHERE event."executionId" = eid)
       AND audit."metadata"->>'toStatus' = (SELECT request."status" FROM public."PaymentRequest" request WHERE request."id" = e."paymentRequestId")) <> 1 THEN
   RAISE EXCEPTION 'registered payment requires one exact same-transaction canonical audit consequence';
 END IF;
 -- Deferred only, after all same-transaction root/fact/impact inserts.
 PERFORM public."jg_assert_registered_payment_intercompany_complete"(eid);
 RETURN NULL;
END

BEGIN
 IF NEW."voucherFileId" IS NULL AND NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentFunding" WHERE "executionId" = NEW."id") THEN
   RAISE EXCEPTION 'legacy payment requires its original voucher';
 END IF;
 RETURN NULL;
END

DECLARE r public."FundAccountBalanceRegistration"; request_id TEXT; round_status TEXT; project_id TEXT; effective_date DATE;
BEGIN
 PERFORM 1 FROM public."RegisteredFundAccount" WHERE "id" = NEW."accountId" FOR UPDATE;
 SELECT "paymentRequestId" INTO STRICT request_id FROM public."PaymentExecution" WHERE "id" = NEW."executionId";
 SELECT "projectId" INTO STRICT project_id FROM public."PaymentRequest" WHERE "id"=request_id;
 SELECT scope."effectiveDate" INTO STRICT effective_date FROM public."jg_registered_operating_scope_lock"(project_id) scope;
 IF NEW."operatingLedgerEffectiveDateAtRegistration" IS DISTINCT FROM effective_date THEN RAISE EXCEPTION 'registered operating scope must freeze the real native project date'; END IF;
 SELECT "status" INTO round_status FROM public."ApprovalInstance" WHERE "businessType" = 'payment_request' AND "businessId" = request_id AND "flowType" = 'payment.approve' ORDER BY "createdAt" DESC LIMIT 1 FOR SHARE;
 IF round_status IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'registered payment latest approval round is not approved'; END IF;
 SELECT * INTO r FROM public."FundAccountBalanceRegistration" WHERE "accountId" = NEW."accountId" AND "status" = 'confirmed' ORDER BY "version" DESC LIMIT 1;
 IF r."id" IS NULL OR r."id" <> NEW."balanceRegistrationId" OR NOT EXISTS (
   SELECT 1 FROM public."RegisteredFundAccount" WHERE "id" = NEW."accountId" AND "writeRevision" > 0 AND xmin::TEXT = (pg_catalog.txid_current() % 4294967296)::TEXT
 ) OR NOT EXISTS (
   SELECT 1 FROM public."PaymentExecution" WHERE "id" = NEW."executionId" AND xmin::text = (pg_catalog.txid_current() % 4294967296)::text
 ) THEN RAISE EXCEPTION 'registered payment must atomically freeze the current same-account reconciliation'; END IF;
 RETURN NEW;
END

DECLARE acc_id TEXT; r public."FundAccountBalanceRegistration"; paid NUMERIC;
BEGIN
 acc_id := NEW."accountId";
 PERFORM 1 FROM public."RegisteredFundAccount" WHERE "id" = acc_id FOR UPDATE;
 SELECT * INTO r FROM public."FundAccountBalanceRegistration" WHERE "accountId" = acc_id AND "status" = 'confirmed' ORDER BY "version" DESC LIMIT 1;
 IF r."id" IS NULL THEN RAISE EXCEPTION 'registered payment account has no confirmed reconciliation'; END IF;
 SELECT coalesce(pg_catalog.sum(p."amountCents"),0) INTO paid FROM public."RegisteredFundPaymentAllocation" p
 WHERE p."accountId" = acc_id AND NOT (p."executionId" = ANY(r."coveredExecutionIds"));
 -- Unknown reconciliation remains unknown with existing uncovered payments;
 -- it is not zero or insufficient. New uncovered postings still require a
 -- known balance at INSERT below. A known negative result cannot be confirmed.
 IF r."balanceYuan" IS NOT NULL AND r."balanceYuan" * 100 < paid THEN
   RAISE EXCEPTION 'registered payment exceeds the confirmed account capacity';
 END IF;
 IF EXISTS (
   WITH RECURSIVE ancestry(current_id,node_id,path) AS (
     SELECT s."id",s."id",ARRAY[s."id"] FROM public."FundAccountSourceBatch" s WHERE s."registrationId" = r."id"
     UNION ALL
     SELECT a.current_id,s."previousSourceBatchId",a.path || s."previousSourceBatchId"
       FROM ancestry a JOIN public."FundAccountSourceBatch" s ON s."id" = a.node_id
       WHERE s."previousSourceBatchId" IS NOT NULL AND NOT(s."previousSourceBatchId" = ANY(a.path))
   ), matches AS (
     SELECT p."id" AS allocation_id,p."amountCents",a.current_id,
            pg_catalog.count(*) OVER(PARTITION BY p."id") AS candidate_count
       FROM public."RegisteredFundPaymentAllocation" p JOIN ancestry a ON a.node_id = p."sourceBatchId"
       WHERE p."accountId" = acc_id AND NOT(p."executionId" = ANY(r."coveredExecutionIds"))
   )
   SELECT 1 FROM matches m JOIN public."FundAccountSourceBatch" s ON s."id" = m.current_id
   WHERE m.candidate_count = 1 GROUP BY s."id",s."amountYuan" HAVING pg_catalog.sum(m."amountCents") > s."amountYuan" * 100
 ) THEN RAISE EXCEPTION 'registered payment exceeds its unambiguous source capacity'; END IF;
 RETURN NULL;
END

DECLARE f public."RegisteredPaymentFunding"; r public."FundAccountBalanceRegistration"; s public."FundAccountSourceBatch"; project_id TEXT;
BEGIN
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = NEW."executionId" AND "accountId" = NEW."accountId";
 SELECT * INTO STRICT r FROM public."FundAccountBalanceRegistration" WHERE "id" = f."balanceRegistrationId" AND "accountId" = f."accountId";
 IF r."balanceYuan" IS NULL THEN RAISE EXCEPTION 'unknown reconciliation cannot fund a new uncovered payment'; END IF;
 SELECT * INTO STRICT s FROM public."FundAccountSourceBatch" WHERE "id" = NEW."sourceBatchId";
 IF s."registrationId" <> r."id" OR f."openingTreatment" <> 'not_included' THEN RAISE EXCEPTION 'allocation requires this payment frozen source'; END IF;
 SELECT request."projectId" INTO STRICT project_id FROM public."PaymentExecution" e JOIN public."PaymentRequest" request ON request."id" = e."paymentRequestId" WHERE e."id" = f."executionId";
 IF s."projectStatus" = 'company_daily' OR (s."projectStatus" = 'project' AND s."projectId" IS DISTINCT FROM project_id) THEN RAISE EXCEPTION 'payment project shortage cannot create an automatic advance or receipt'; END IF;
 IF EXISTS (
   WITH RECURSIVE ancestry(current_id,node_id,path) AS (
     SELECT source."id",source."id",ARRAY[source."id"] FROM public."FundAccountSourceBatch" source WHERE source."registrationId" = r."id"
     UNION ALL SELECT a.current_id,parent."previousSourceBatchId",a.path || parent."previousSourceBatchId"
       FROM ancestry a JOIN public."FundAccountSourceBatch" parent ON parent."id" = a.node_id
       WHERE parent."previousSourceBatchId" IS NOT NULL AND NOT(parent."previousSourceBatchId" = ANY(a.path))
   ), candidates AS (
     SELECT p."id",coalesce(pg_catalog.array_agg(a.current_id) FILTER(WHERE a.current_id IS NOT NULL),ARRAY[]::TEXT[]) AS candidate_ids FROM public."RegisteredFundPaymentAllocation" p
       LEFT JOIN ancestry a ON a.node_id = p."sourceBatchId"
       WHERE p."accountId" = f."accountId" AND NOT(p."executionId" = ANY(r."coveredExecutionIds"))
       GROUP BY p."id"
   ) SELECT 1 FROM candidates c WHERE pg_catalog.cardinality(c.candidate_ids) = 0 OR (pg_catalog.cardinality(c.candidate_ids) <> 1 AND NEW."sourceBatchId" = ANY(c.candidate_ids))
 ) THEN RAISE EXCEPTION 'source distribution is unresolved after reconciliation; no automatic allocation is allowed'; END IF;
 RETURN NEW;
END

BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'RegisteredContractHistoryRevision' THEN RAISE EXCEPTION 'history revision guard attached to wrong relation'; END IF;
 IF TG_OP = 'INSERT' AND pg_catalog.pg_trigger_depth() >= 2 AND NEW."revision" = 0 AND EXISTS(SELECT 1 FROM public."Contract" WHERE "id" = NEW."contractId") THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND pg_catalog.pg_trigger_depth() >= 2 AND NEW."contractId" = OLD."contractId" AND NEW."revision" = OLD."revision" + 1 THEN RETURN NEW; END IF;
 -- Preserve legitimate original Contract deletion; no payment/history row is
 -- removed by this technical table's cascade. Runtime direct DELETE is denied.
 IF TG_OP = 'DELETE' AND NOT EXISTS(SELECT 1 FROM public."Contract" WHERE "id" = OLD."contractId") THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'history revision is controlled by its real parent triggers';
END

BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'Contract' OR TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'history marker creation requires real new Contract'; END IF;
 INSERT INTO public."RegisteredContractHistoryRevision"("contractId","revision") VALUES(NEW."id",0);
 RETURN NEW;
END

DECLARE current_revision BIGINT;
BEGIN
 BEGIN
   SELECT "revision" INTO current_revision FROM public."RegisteredContractHistoryRevision" WHERE "contractId" = contract_id FOR UPDATE NOWAIT;
 EXCEPTION WHEN lock_not_available THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='contract history basis is being changed; query original result before retry';
 END;
 RETURN current_revision; -- missing marker remains NULL, never inserted here
END

BEGIN
 IF pg_catalog.current_setting('transaction_isolation') <> 'serializable' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='registered payment history basis requires Serializable transaction'; END IF;
 RETURN public."jg_registered_history_try_lock_internal"(contract_id);
END

SELECT pg_catalog.jsonb_build_array(row_value->'id',row_value->'contractId',row_value->'contractVersionId',row_value->'paymentTermsVersionId',
  row_value->'takeoverStatus',row_value->'historicalBalanceConfirmedAt',row_value->'activatedAt',row_value->'updatedAt',
  row_value->'historicalPaidCents',row_value->'historicalProxyPaidCents',row_value->'historicalAdvancePaidCents');

DECLARE old_row JSONB; new_row JSONB; old_member BOOLEAN := FALSE; new_member BOOLEAN := FALSE; parent_id TEXT; revision_seen BIGINT;
BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'ContractTakeover' THEN RAISE EXCEPTION 'history revision writer attached to wrong relation'; END IF;
 IF TG_OP <> 'INSERT' THEN old_row := pg_catalog.to_jsonb(OLD); old_member := public."jg_registered_history_basis_member"(old_row); END IF;
 IF TG_OP <> 'DELETE' THEN new_row := pg_catalog.to_jsonb(NEW); new_member := public."jg_registered_history_basis_member"(new_row); END IF;
 IF (old_member OR new_member) AND (TG_OP <> 'UPDATE' OR public."jg_registered_history_basis_tuple"(old_row) IS DISTINCT FROM public."jg_registered_history_basis_tuple"(new_row)) THEN
   FOR parent_id IN SELECT DISTINCT value FROM pg_catalog.unnest(ARRAY[CASE WHEN old_member THEN old_row->>'contractId' END,CASE WHEN new_member THEN new_row->>'contractId' END]) AS parent(value) WHERE value IS NOT NULL ORDER BY value LOOP
     revision_seen := public."jg_registered_history_try_lock_internal"(parent_id);
     IF revision_seen IS NULL THEN RAISE EXCEPTION 'contract history revision marker is missing'; END IF;
     UPDATE public."RegisteredContractHistoryRevision" SET "revision" = "revision" + 1 WHERE "contractId" = parent_id;
   END LOOP;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END

DECLARE e public."PaymentExecution"; f public."RegisteredPaymentFunding"; request public."PaymentRequest";
 root public."InterEntityRelationshipEntry"; fact public."OperatingFact"; effect public."OperatingImpactEntry";
 frozen_source_type TEXT; cross_company BOOLEAN; root_count BIGINT; fact_count BIGINT; impact_count BIGINT;
 due_count BIGINT; due_total NUMERIC; expected_payables JSONB; snapshot_payables JSONB; expected_payable_count BIGINT;
 payable_count BIGINT := 0; funds_count BIGINT := 0; proxy_count BIGINT := 0; source_id TEXT; funds_kind TEXT;
BEGIN
 SELECT * INTO STRICT e FROM public."PaymentExecution" WHERE "id" = execution_id;
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = execution_id;
 SELECT * INTO STRICT request FROM public."PaymentRequest" WHERE "id" = e."paymentRequestId";
 SELECT event."payload"->'writeAuthority'->>'sourceType' INTO STRICT frozen_source_type
 FROM public."RegisteredPaymentEvent" event WHERE event."executionId"=execution_id;
 IF frozen_source_type NOT IN ('settlement','contract_due','contract_advance') OR frozen_source_type IS NULL THEN
   RAISE EXCEPTION 'registered payment requires its frozen source applicability';
 END IF;
 cross_company := f."actualPayerKind"='participating_company' AND f."actualPayerId"<>e."companyEntityIdSnapshot";
 SELECT pg_catalog.count(*) INTO root_count FROM public."InterEntityRelationshipEntry"
 WHERE "paymentExecutionId"=execution_id AND "entryKind"='proxy_payment' AND "direction"='increase';
 IF cross_company THEN
   IF root_count<>1 THEN RAISE EXCEPTION 'registered cross-company payment requires exactly one debt root'; END IF;
   SELECT * INTO STRICT root FROM public."InterEntityRelationshipEntry"
   WHERE "paymentExecutionId"=execution_id AND "entryKind"='proxy_payment' AND "direction"='increase';
   PERFORM public."jg_assert_registered_payment_relationship"(root);
 ELSIF root_count<>0 THEN
   RAISE EXCEPTION 'same-company or public-cash payment cannot create an intercompany debt root';
 END IF;
 -- Adapter's payable basis is immutable Execution.settlementId plus positive
 -- immutable due-payment allocation rows, never a guessed zero or future request.
 SELECT pg_catalog.count(*),coalesce(pg_catalog.sum(a."amountCents"),0) INTO due_count,due_total
 FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment';
 IF EXISTS(SELECT 1 FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment'
   AND (a."paymentRequestId"<>e."paymentRequestId" OR a."projectId"<>request."projectId" OR a."contractId"<>request."contractId"
        OR a."amountCents"<=0 OR coalesce(pg_catalog.length(pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId"))),0)=0)) THEN
   RAISE EXCEPTION 'registered due allocation must belong to its frozen payment source';
 END IF;
 IF frozen_source_type='contract_due' AND e."settlementId" IS NULL THEN
   IF due_count=0 OR due_total<>e."amountCents" THEN RAISE EXCEPTION 'registered contract-due payment requires its full immutable payable allocation basis'; END IF;
 ELSIF due_count<>0 THEN
   RAISE EXCEPTION 'registered payment cannot add a due allocation outside its application source path';
 END IF;
 SELECT coalesce(pg_catalog.jsonb_object_agg(grouped.source_id,grouped.amount::TEXT),'{}'::JSONB) INTO expected_payables
 FROM (SELECT pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId")) AS source_id,pg_catalog.sum(a."amountCents") AS amount
       FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment'
       GROUP BY pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId"))) grouped;
 IF due_count=0 AND e."settlementId" IS NOT NULL THEN
   IF pg_catalog.length(pg_catalog.btrim(e."settlementId"))=0 THEN RAISE EXCEPTION 'registered settlement source is empty'; END IF;
   expected_payables:=pg_catalog.jsonb_build_object(pg_catalog.btrim(e."settlementId"),e."amountCents"::TEXT);
 END IF;
 SELECT pg_catalog.count(*) INTO fact_count FROM public."OperatingFact" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 SELECT pg_catalog.count(*) INTO impact_count FROM public."OperatingImpactEntry" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 -- NULL frozen scope permits no projection at all. Once any projection exists,
 -- including a later legitimate append, it must be the complete same graph.
 IF f."operatingLedgerEffectiveDateAtRegistration" IS NULL AND fact_count=0 AND impact_count=0 THEN RETURN; END IF;
 IF fact_count<>1 THEN RAISE EXCEPTION 'registered projected payment requires exactly one canonical fact'; END IF;
 SELECT * INTO STRICT fact FROM public."OperatingFact" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 IF NOT coalesce(fact."projectId"=request."projectId" AND fact."sourceVersion"=1 AND fact."entryKind"='original' AND fact."status"='confirmed'
   AND fact."factKind"='downstream_payment' AND fact."operatingLevel"=CASE WHEN cross_company THEN 'inter_subject' ELSE 'project' END
   AND fact."amountCents"=e."amountCents" AND fact."currencyCode"='CNY' AND fact."direction"='outflow' AND fact."evidenceLevel"='A'
   AND fact."occurredAt"=e."paidAt" AND fact."confirmedAt"=e."createdAt" AND fact."confirmedByUserId"=e."executedByUserId" AND fact."recordedByUserId"=e."executedByUserId"
   AND fact."idempotencyKey"='payment_execution:'||execution_id
   AND fact."debtorSubjectKind"='participating_company' AND fact."debtorSubjectId"=e."companyEntityIdSnapshot"
   AND fact."approvedPayerSubjectKind"='participating_company' AND fact."approvedPayerSubjectId"=e."companyEntityIdSnapshot"
   AND fact."actualPayerSubjectKind"=f."actualPayerKind" AND fact."actualPayerSubjectId"=f."actualPayerId"
   AND fact."payeeSubjectKind"='downstream_counterparty' AND pg_catalog.length(pg_catalog.btrim(fact."payeeSubjectId"))>0
   AND fact."sourceSnapshot"->>'payeeVersionId'=fact."payeeSubjectId"
   AND fact."sourceSnapshot"->>'paymentSourceType'=frozen_source_type
   AND fact."sourceSnapshot"->'settlementId'=coalesce(pg_catalog.to_jsonb(e."settlementId"),'null'::JSONB)
   AND (f."operatingLedgerEffectiveDateAtRegistration" IS NULL OR fact."operatingLedgerEffectiveDateSnapshot"=f."operatingLedgerEffectiveDateAtRegistration")
   AND public."jg_registered_payment_source_matches"(execution_id,request."projectId",e."amountCents",f."actualPayerKind",f."actualPayerId"),FALSE) THEN
   RAISE EXCEPTION 'registered canonical fact must match its exact frozen payment subjects and applicability';
 END IF;
 IF pg_catalog.jsonb_typeof(fact."sourceSnapshot"->'payableAllocations') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'registered canonical fact requires its payable source set'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(fact."sourceSnapshot"->'payableAllocations') item
   WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object' OR pg_catalog.jsonb_typeof(item->'sourceId') IS DISTINCT FROM 'string'
     OR coalesce(pg_catalog.length(pg_catalog.btrim(item->>'sourceId')),0)=0 OR pg_catalog.jsonb_typeof(item->'amountCents') IS DISTINCT FROM 'string'
     OR NOT coalesce(item->>'amountCents' ~ '^[1-9][0-9]*$',FALSE)) THEN RAISE EXCEPTION 'registered canonical payable source is invalid'; END IF;
 SELECT coalesce(pg_catalog.jsonb_object_agg(grouped.source_id,grouped.amount::TEXT),'{}'::JSONB) INTO snapshot_payables
 FROM (SELECT pg_catalog.btrim(item->>'sourceId') AS source_id,pg_catalog.sum((item->>'amountCents')::NUMERIC) AS amount
       FROM pg_catalog.jsonb_array_elements(fact."sourceSnapshot"->'payableAllocations') item GROUP BY pg_catalog.btrim(item->>'sourceId')) grouped;
 IF snapshot_payables<>expected_payables THEN RAISE EXCEPTION 'registered canonical payable snapshot must match its immutable execution allocations'; END IF;
 funds_kind:=CASE WHEN f."actualPayerKind"='public_cash' THEN 'public_cash_funds_decrease' ELSE 'company_project_funds_decrease' END;
 FOR effect IN SELECT * FROM public."OperatingImpactEntry" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id LOOP
   IF effect."factId"<>fact."id" OR effect."projectId"<>fact."projectId" THEN RAISE EXCEPTION 'registered impact must belong to its one canonical fact'; END IF;
   IF effect."sourceImpactKey" LIKE 'payable:%' THEN
     source_id:=pg_catalog.substr(effect."sourceImpactKey",9);
     IF NOT coalesce(expected_payables ? source_id AND effect."impactKind"='payable_decrease' AND effect."direction"='decrease'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':payable:'||source_id
       AND effect."amountCents"=(expected_payables->>source_id)::BIGINT AND effect."subjectRole"='payee'
       AND effect."subjectKind"=fact."payeeSubjectKind" AND effect."subjectId"=fact."payeeSubjectId",FALSE) THEN
       RAISE EXCEPTION 'registered payable impact must match its exact immutable allocation and frozen fact payee'; END IF;
     payable_count:=payable_count+1;
   ELSIF effect."sourceImpactKey"=funds_kind THEN
     IF NOT coalesce(f."openingTreatment"='not_included' AND effect."impactKind"=funds_kind AND effect."direction"='decrease'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':funds' AND effect."amountCents"=e."amountCents"
       AND effect."subjectRole"='actual_payer' AND effect."subjectKind"=f."actualPayerKind" AND effect."subjectId"=f."actualPayerId",FALSE) THEN
       RAISE EXCEPTION 'registered funds impact must match the unpaid-in-opening frozen actual payer'; END IF;
     funds_count:=funds_count+1;
   ELSIF effect."sourceImpactKey"='inter_subject_proxy_payment' THEN
     IF NOT coalesce(cross_company AND effect."impactKind"='inter_subject_balance_increase' AND effect."direction"='increase'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':proxy' AND effect."amountCents"=e."amountCents"
       AND effect."subjectRole"='actual_payer' AND effect."subjectKind"='participating_company' AND effect."subjectId"=f."actualPayerId"
       AND effect."impactSnapshot"->'debtor'=pg_catalog.jsonb_build_object('kind','participating_company','id',e."companyEntityIdSnapshot")
       AND effect."impactSnapshot"->'approvedPayer'=pg_catalog.jsonb_build_object('kind','participating_company','id',e."companyEntityIdSnapshot")
       AND effect."impactSnapshot"->'actualPayer'=pg_catalog.jsonb_build_object('kind','participating_company','id',f."actualPayerId"),FALSE) THEN
       RAISE EXCEPTION 'registered proxy impact must match its one frozen debt root'; END IF;
     proxy_count:=proxy_count+1;
   ELSE RAISE EXCEPTION 'registered canonical graph cannot contain an extra unrecognized impact'; END IF;
 END LOOP;
 SELECT pg_catalog.count(*) INTO expected_payable_count FROM pg_catalog.jsonb_object_keys(expected_payables);
 IF payable_count<>expected_payable_count OR funds_count<>CASE WHEN f."openingTreatment"='not_included' THEN 1 ELSE 0 END
   OR proxy_count<>CASE WHEN cross_company THEN 1 ELSE 0 END THEN
   RAISE EXCEPTION 'registered canonical graph is missing an applicable payable, funds or proxy consequence';
 END IF;
END

BEGIN
 IF EXISTS(SELECT 1 FROM public."RegisteredPaymentFunding" f WHERE f."executionId"=NEW."paymentExecutionId") THEN
   PERFORM public."jg_assert_registered_payment_intercompany_complete"(NEW."paymentExecutionId");
 END IF;
 RETURN NULL;
END

