    PERFORM jg_validate_canonical_wage_operating_fact(NEW);
  ELSIF NEW."costBearingCompanySubjectKind" IS NULL OR NEW."payeeSubjectKind" IS NULL THEN
    RAISE EXCEPTION '工资事实必须填写成本承担公司和收款主体' USING ERRCODE = '23514';
  END IF;
END IF;

